content.content:
1	/**
2	 * 页面内 DOM 扫描（移植自 temu-plugin/content.js）
3	 * 全部通过 page.evaluate 执行，避免 Playwright 选择器与 chip 竞态。
4	 */
5	import { log } from './logger.js';
6	
7	const DOM_HELPERS = `
8	  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
9	  const visible = (el) => {
10	    if (!el) return false;
11	    const r = el.getBoundingClientRect();
12	    return r.width > 0 && r.height > 0;
13	  };
14	  const textEls = (re, maxLen = 40) =>
15	    [...document.querySelectorAll('*')].filter((e) => {
16	      const t = (e.textContent || '').trim();
17	      return re.test(t) && t.length <= maxLen;
18	    });
19	  const clickableAncestor = (el) => {
20	    let p = el;
21	    for (let i = 0; i < 6 && p; i++, p = p.parentElement) {
22	      if (p.tagName === 'BUTTON' || p.getAttribute('role') === 'button' || p.onclick) return p;
23	    }
24	    return el;
25	  };
26	  const realClick = (el) => {
27	    if (!el) return;
28	    const opts = { bubbles: true, cancelable: true, view: window };
29	    for (const type of ['pointerdown', 'mousedown', 'mouseup', 'click']) {
30	      el.dispatchEvent(new MouseEvent(type, opts));
31	    }
32	  };
33	  const waitFor = async (fn, timeout = 8000, step = 300) => {
34	    const t0 = Date.now();
35	    while (Date.now() - t0 < timeout) {
36	      const v = fn();
37	      if (v) return v;
38	      await sleep(step);
39	    }
40	    return null;
41	  };
42	  function readChipCount(label) {
43	    const re = new RegExp(label);
44	    for (const card of document.querySelectorAll('[class*="use-quick-field_tsx_card__"]')) {
45	      if (!re.test(card.textContent || '')) continue;
46	      const cnt = card.querySelector('[class*="countDistance"]');
47	      if (cnt && /\\d/.test(cnt.textContent || '')) {
48	        return Number((cnt.textContent || '').replace(/[^\\d]/g, ''));
49	      }
50	      const m = (card.textContent || '').match(new RegExp(label + '[^\\\\d]{0,3}([\\\\d,]+)'));
51	      if (m) return Number(m[1].replace(/,/g, ''));
52	    }
53	    const all = [...document.querySelectorAll('*')];
54	    const labels = all
55	      .filter((e) => re.test(e.textContent || '') && (e.textContent || '').trim().length < 24)
56	      .sort((a, b) => (a.textContent || '').length - (b.textContent || '').length);
57	    for (const el of labels) {
