1	/**
2	 * 单店完整扫描（对齐插件能力，在 Playwright 页内执行）
3	 *  - onSaleCount：countStatus 接口 / tab
4	 *  - trafficWatchCount + watchItems：chip + 可选主动筛选扫明细
5	 *  - trafficDeclineCount + declineItems：行内徽标
6	 */
7	import { log } from './logger.js';
8	import { closePopups } from './popups.js';
9	import { readPassiveTraffic, scanWatchList, waitForGrid } from './domScan.js';
10	
11	/**
12	 * @param {import('playwright').Page} page
13	 * @param {string} storeName
14	 * @param {object} cfg
15	 * @param {{ forceWatchScan?: boolean, prevWatch?: number|null }} [opts]
16	 */
17	export async function scanStore(page, storeName, cfg, opts = {}) {
18	  const statusP = page
19	    .waitForResponse(
20	      (r) =>
21	        /visage-agent-seller\/product\/skc\/countStatus/.test(r.url()) &&
22	        r.request().method() === 'POST',
23	      { timeout: 20000 },
24	    )
25	    .catch(() => null);
26	
27	  await page.goto(cfg.goodsListUrl, { waitUntil: 'commit' }).catch(() => {});
28	  const statusResp = await statusP;
29	  await closePopups(page);
30	  await waitForGrid(page);
31	  await page.waitForTimeout(1500);
32	
33	  let onSaleCount = readOnSaleFromStatus(await readStatusJson(statusResp));
34	  if (onSaleCount != null) {
35	    log.info(`[${storeName}] 在售读自 countStatus：${onSaleCount}`);
36	  } else {
37	    onSaleCount = await readOnSaleCount(page);
38	    log.warn(`[${storeName}] countStatus 回落 tab：${onSaleCount}`);
39	  }
40	
41	  // 被动读 chip + 徽标 + 当前页明细
42	  let passive = await readPassiveTraffic(page);
43	  // 网格未好再等一轮
44	  if (!passive.gridReady) {
45	    await waitForGrid(page);
46	    await page.waitForTimeout(1200);
47	    passive = await readPassiveTraffic(page);
48	  }
49	
50	  let trafficWatchCount = passive.trafficWatch;
51	  let watchItems = passive.watchItems || [];
52	  let trafficDeclineCount =
53	    typeof passive.trafficDecline === 'number' ? passive.trafficDecline : null;
54	  let declineItems = passive.declineItems || [];
55	
56	  // 待关注：chip 读不到时尝试点筛选读「共有 N 条」（旧逻辑兜底）
57	  if (trafficWatchCount == null) {
58	    const legacy = await readTrafficByClickFilter(page);
59	    if (legacy != null) trafficWatchCount = legacy;
60	  }
61	
62	  // 待关注增加 或 强制扫 / 有待关注但当前页明细为空 → 主动筛选捞明细
63	  const prevWatch = opts.prevWatch;
64	  const watchIncreased =
65	    typeof prevWatch === 'number' &&
66	    typeof trafficWatchCount === 'number' &&
67	    trafficWatchCount > prevWatch;
68	  const needWatchScan =
69	    opts.forceWatchScan ||
70	    watchIncreased ||
71	    (typeof trafficWatchCount === 'number' &&
72	      trafficWatchCount > 0 &&
73	      watchItems.length === 0);
74	
75	  if (needWatchScan && trafficWatchCount !== 0) {
