96	/**
97	 * 切换到目标店铺（会话级）。已是当前店则 ok。
98	 * @returns {Promise<{ok:boolean,msg:string}>}
99	 */
100	export async function switchSessionStore(page, target) {
101	  const cur = await readCurrentStoreName(page);
102	  if (cur && cur === target) {
103	    log.info(`已是当前店：${target}`);
104	    return { ok: true, msg: 'already' };
105	  }
106	  log.info(`会话切店 → ${target}（当前=${cur || '未知'}）`);
107	  // Playwright page.evaluate 只接受 1 个参数，多个值必须包成对象
108	  const result = await page.evaluate(async ({ helpers, targetName }) => {
109	    // eslint-disable-next-line no-eval
110	    eval(helpers);
111	    if (!(await openStoreModal())) return { ok: false, msg: '打不开切换店铺弹窗' };
112	    await sleep(400);
113	    const esc = String(targetName).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
114	    const re = new RegExp(esc);
115	    // 弹窗内含店名的行
116	    const candidates = [...document.querySelectorAll('div,li,tr,span')].filter((e) => {
117	      if (!visible(e)) return false;
118	      const t = (e.textContent || '').trim();
119	      return re.test(t) && /切换|半托管|全托管/.test(t) && t.length < 200;
120	    });
121	    // 取最短匹配容器
122	    candidates.sort((a, b) => (a.textContent || '').length - (b.textContent || '').length);
123	    const row = candidates[0];
124	    if (!row) return { ok: false, msg: '弹窗里没找到店铺 ' + targetName };
125	    let btn = [...row.querySelectorAll('button,[role=button]')].find(
126	      (b) => /^\s*切换\s*$/.test((b.textContent || '').trim()) && !b.disabled && b.getAttribute('aria-disabled') !== 'true',
127	    );
128	    if (!btn) {
129	      const allSwitch = textEls(/^切换$/, 6)
130	        .map(clickableAncestor)
131	        .filter((b) => b && !b.disabled && visible(b));
132	      btn = allSwitch.find((b) => row.contains(b)) || allSwitch[allSwitch.length - 1];
133	    }
134	    if (!btn) return { ok: false, msg: '没找到可点的切换按钮（可能已是当前店）' };
135	    realClick(btn);
136	    return { ok: true, msg: 'clicked' };
137	  }, { helpers: SWITCH_HELPERS, targetName: target });
138	
139	  if (!result.ok) {
140	    log.warn(`切店失败：${result.msg}`);
141	    await page.keyboard.press('Escape').catch(() => {});
142	    return result;
143	  }
144	  // 等顶栏店名变化或导航完成
145	  await page.waitForTimeout(2500);
146	  const deadline = Date.now() + 25000;
147	  while (Date.now() < deadline) {
148	    const name = await readCurrentStoreName(page);
149	    if (name === target) {
150	      log.info(`切店成功：${target}`);
151	      return { ok: true, msg: 'switched' };
152	    }
153	    await page.waitForTimeout(800);
154	  }
155	  const after = await readCurrentStoreName(page);
156	  if (after === target) return { ok: true, msg: 'switched-late' };
157	  log.warn(`切店超时，当前显示=${after || '未知'}，目标=${target}`);
158	  return { ok: false, msg: `timeout current=${after}` };
159	}
