1	/**
2	 * 入口分流（2026-07-30 起默认隔离）：
3	 *  - 本机默认：仅浏览器流量（待关注 / 近期下降 / 在售数字）
4	 *  - 赛狐上下架：独立 `npm run sellfox:*`，部署在固定 IP 服务器
5	 *  - 联调全量：config.fullRun=true 或 FULL_RUN=1（动态加载 fullRun，本机包可不带 sellfox）
6	 */
7	import { launchBrowser, isLoggedIn } from './browser.js';
8	import { listStores, switchStore } from './stores.js';
9	import { scanStore } from './monitor.js';
10	import { closePopups } from './popups.js';
11	import { loadState, saveState, diffStore, mergeSnapshot } from './state.js';
12	import { sendFeishu } from './feishu.js';
13	import { log } from './logger.js';
14	
15	export async function runOnce(cfg) {
16	  // fullRun 已在 loadConfig 里综合 env；再挡一层显式 FULL_RUN=0
17	  const forceOff = process.env.FULL_RUN === '0' || process.env.FULL_RUN === 'false';
18	  const useFull = !forceOff && cfg.fullRun === true;
19	
20	  if (useFull) {
21	    log.info('全量监测（赛狐上下架 + 浏览器流量）— 需本机 IP 在赛狐白名单');
22	    // 动态加载：同事本机包可不带 src/sellfox，默认流量路径不依赖它
23	    try {
24	      const { runFullOnce } = await import('./fullRun.js');
25	      return runFullOnce(cfg);
26	    } catch (e) {
27	      log.error('全量模块加载失败（本机流量包可能未含赛狐代码）：', e.message);
28	      log.warn('回退为仅浏览器流量监测');
29	      return runBrowserOnly(cfg);
30	    }
31	  }
32	
33	  log.info('仅浏览器流量监测（赛狐上下架请用服务器 temu-sellfox）');
34	  return runBrowserOnly(cfg);
35	}
36	
37	/** 旧版：只跑 Playwright，不调用赛狐 */
38	export async function runBrowserOnly(cfg) {
39	  const { context, page } = await launchBrowser(cfg);
40	  try {
41	    if (!(await isLoggedIn(page, cfg))) {
42	      const err = new Error('未登录。请先运行 `npm run login` 完成一次人工登录。');
43	      err.code = 'NOT_LOGGED_IN';
44	      throw err;
45	    }
46	    await closePopups(page);
47	
48	    const storeNames =
49	      cfg.stores === 'all' && cfg.storeList.length === 0
50	        ? await listStores(page)
51	        : cfg.storeList;
52	    const singleStore = !storeNames || storeNames.length <= 1;
53	    const stores = singleStore ? [(storeNames && storeNames[0]) || null] : storeNames;
54	    if (singleStore) {
55	      log.info('按单店铺监测聚合视图，店铺：', (storeNames && storeNames[0]) || '(当前)');
56	    }
57	
58	    const state = loadState();
59	    state.stores = state.stores || {};
60	    const allEvents = [];
61	    const summaries = [];
62	
63	    for (const store of stores) {
64	      const label = store || '(当前店铺)';
65	      try {
66	        if (store && !singleStore) {
67	          const ok = await switchStore(page, store, cfg);
68	          if (!ok) {
69	            log.warn(`切换到「${store}」失败，跳过`);
70	            continue;
71	          }
72	        }
73	        const prev = state.stores[label];
74	        const result = await scanStore(page, label, cfg, {
75	          prevWatch: prev?.trafficWatchCount,
76	        });
77	        log.info('扫描结果：', result);
78	        summaries.push(result);
79	        const events = diffStore(prev, result, cfg.alerts);
80	        for (const ev of events) allEvents.push({ store: label, ...ev });
81	        state.stores[label] = mergeSnapshot(prev, result);
82	      } catch (e) {
83	        log.error(`店铺「${label}」监测出错：`, e.message);
84	      }
85	    }
86	
87	    saveState(state);
88	
89	    if (allEvents.length > 0) {
90	      const lines = [];
91	      const byStore = {};
92	      for (const ev of allEvents) (byStore[ev.store] ||= []).push(ev);
93	      for (const [store, evs] of Object.entries(byStore)) {
94	        lines.push(`**🏬 ${store}**`);
95	        for (const ev of evs) {
96	          const icon = ev.type === 'onSaleDrop' ? '📉' : '⚠️';
97	          lines.push(`${icon} ${ev.text}`);
98	        }
99	        lines.push('');
100	      }
