1	/**
2	 * 会话级切店（右上角头像 → 切换 →「切换店铺」弹窗）
3	 * 对齐 temu-plugin content.js，多 mall 共用账号时必须用此方式，不能用「来源店铺」筛选。
4	 */
5	import { log } from './logger.js';
6	
7	// 注意：经 page.evaluate → eval(helpers) 注入。必须用 function/var，不能用 const/let
8	// （const/let 不泄漏到 evaluate 外层；切店回调里直接调 realClick/sleep/visible 会挂）。
9	const SWITCH_HELPERS = `
10	  function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }
11	  function visible(el) {
12	    if (!el) return false;
13	    const r = el.getBoundingClientRect();
14	    return r.width > 0 && r.height > 0;
15	  }
16	  function textEls(re, maxLen = 40) {
17	    return [...document.querySelectorAll('*')].filter((e) => {
18	      const t = (e.textContent || '').trim();
19	      return re.test(t) && t.length <= maxLen;
20	    });
21	  }
22	  function clickableAncestor(el) {
23	    let p = el;
24	    for (let i = 0; i < 6 && p; i++, p = p.parentElement) {
25	      if (p.tagName === 'BUTTON' || p.getAttribute('role') === 'button') return p;
26	    }
27	    return el;
28	  }
29	  function realClick(el) {
30	    if (!el) return;
31	    const opts = { bubbles: true, cancelable: true, view: window };
32	    for (const type of ['pointerdown', 'mousedown', 'mouseup', 'click']) {
33	      el.dispatchEvent(new MouseEvent(type, opts));
34	    }
35	  }
36	  async function waitFor(fn, timeout = 8000, step = 300) {
37	    const t0 = Date.now();
38	    while (Date.now() - t0 < timeout) {
39	      const v = fn();
40	      if (v) return v;
41	      await sleep(step);
42	    }
43	    return null;
44	  }
45	  function findStoreNameEl() {
46	    const W = window.innerWidth;
47	    let best = null;
48	    for (const el of document.querySelectorAll('span,a,div,button,p')) {
49	      const t = (el.textContent || '').trim();
50	      if (!/^[A-Za-z][A-Za-z0-9]*(?:\\s[A-Za-z0-9]+){0,3}$/.test(t)) continue;
51	      if (t.length < 2 || t.length > 30) continue;
52	      if (/^(Seller Central|Beta|NEW|SKC|SKU|USD|Best Seller)$/i.test(t)) continue;
53	      if (/^[A-Z0-9]+$/.test(t)) continue;
54	      if (el.children.length > 2) continue;
55	      const r = el.getBoundingClientRect();
56	      if (r.width === 0 || r.top < 0 || r.top > 90) continue;
57	      if (r.left < W * 0.5) continue;
58	      if (!best || r.left > best.left) best = { el, left: r.left };
59	    }
60	    return best ? best.el : null;
61	  }
62	  function readStoreName() {
63	    const el = findStoreNameEl();
64	    return el ? (el.textContent || '').trim() : null;
65	  }
66	  async function openStoreModal() {
67	    // 点顶栏最右侧区域的「切换」
68	    const switches = textEls(/^切换$/, 6).filter(visible);
69	    let btn = switches[switches.length - 1];
70	    if (!btn) {
71	      // 点头像附近
72	      const av = [...document.querySelectorAll('img,div,span')].find((e) => {
73	        const r = e.getBoundingClientRect();
74	        return r.top >= 0 && r.top < 80 && r.left > window.innerWidth * 0.85 && r.width > 20 && r.height > 20;
75	      });
76	      if (av) realClick(av);
77	      await sleep(400);
78	      const again = textEls(/^切换$/, 6).filter(visible);
79	      btn = again[again.length - 1];
80	    }
81	    if (btn) realClick(clickableAncestor(btn));
82	    await sleep(600);
83	    const modal = await waitFor(() => {
84	      const t = document.body.innerText || '';
85	      return /切换店铺|您的账户存在/.test(t) ? true : null;
86	    }, 5000, 200);
87	    return !!modal;
88	  }
89	`;
90	
91	export async function readCurrentStoreName(page) {
92	  return page.evaluate((helpers) => {
93	    // eslint-disable-next-line no-eval
94	    eval(helpers);
95	    return readStoreName();
96	  }, SWITCH_HELPERS);
97	}
98	
99	/**
100	 * 切换到目标店铺（会话级）。已是当前店则 ok。
101	 * @returns {Promise<{ok:boolean,msg:string}>}
102	 */
103	export async function switchSessionStore(page, target) {
104	  const cur = await readCurrentStoreName(page);
105	  if (cur && cur === target) {
106	    log.info(`已是当前店：${target}`);
107	    return { ok: true, msg: 'already' };
108	  }
