1	/**
2	 * 入口分流（2026-07-30 起默认隔离）：
3	 *  - 本机默认：仅浏览器流量（待关注 / 近期下降 / 在售数字）
4	 *  - 赛狐上下架：独立 `npm run sellfox:*`，部署在固定 IP 服务器
5	 *  - 联调全量：config.fullRun=true 或 FULL_RUN=1（动态加载 fullRun，本机包可不带 sellfox）
6	 */
7	import { launchBrowser, isLoggedIn } from './browser.js';
8	import { scanStore } from './monitor.js';
9	import { closePopups } from './popups.js';
10	import { loadState, saveState, diffStore, mergeSnapshot } from './state.js';
11	import { sendFeishu } from './feishu.js';
12	import { switchSessionStore, readCurrentStoreName } from './sessionStores.js';
13	import { log } from './logger.js';
14	
15	export async function runOnce(cfg) {
16	  // fullRun 已在 loadConfig 里综合 env；再挡一层显式 FULL_RUN=0
17	  const forceOff = process.env.FULL_RUN === '0' || process.env.FULL_RUN === 'false';
18	  const useFull = !forceOff && cfg.fullRun === true;
19	
20	  if (useFull) {
21	    log.info('全量监测（赛狐上下架 + 浏览器流量）— 需本机 IP 在赛狐白名单');
22	    // 动态加载：同事本机包可不带 src/sellfox，默认流量路径不依赖它
23	    try {
24	      const { runFullOnce } = await import('./fullRun.js');
25	      return runFullOnce(cfg);
26	    } catch (e) {
27	      log.error('全量模块加载失败（本机流量包可能未含赛狐代码）：', e.message);
28	      log.warn('回退为仅浏览器流量监测');
29	      return runBrowserOnly(cfg);
30	    }
31	  }
32	
33	  log.info('仅浏览器流量监测（赛狐上下架请用服务器 temu-sellfox）');
34	  return runBrowserOnly(cfg);
35	}
36	
37	/**
38	 * 仅浏览器流量/在售：多店走会话级切店（头像→切换店铺），
39	 * 不再用「来源店铺」筛选（那只是商品来源过滤，切不了会话）。
40	 */
41	export async function runBrowserOnly(cfg) {
42	  const { context, page } = await launchBrowser(cfg);
43	  try {
44	    if (!(await isLoggedIn(page, cfg))) {
45	      const err = new Error('未登录。请先运行 `npm run login` 完成一次人工登录。');
46	      err.code = 'NOT_LOGGED_IN';
47	      throw err;
48	    }
49	    await closePopups(page);
50	
51	    let stores = Array.isArray(cfg.storeList)
52	      ? cfg.storeList.map(String).filter(Boolean)
53	      : [];
54	    if (!stores.length) {
55	      const cur = await readCurrentStoreName(page);
56	      stores = [cur || '(当前店铺)'];
57	      log.info('未配置 storeList，监测当前店：', stores[0]);
58	    } else if (stores.length === 1) {
59	      log.info('单店监测：', stores[0]);
60	    } else {
61	      log.info('多店会话轮巡：', stores.join(', '));
62	    }
63	
64	    const state = loadState();
65	    state.stores = state.stores || {};
66	    const allEvents = [];
67	    const summaries = [];
68	
69	    for (const store of stores) {
70	      const label = store || '(当前店铺)';
