1	import { readFileSync, writeFileSync, existsSync, copyFileSync } from 'node:fs';
2	import { fileURLToPath } from 'node:url';
3	import { dirname, resolve } from 'node:path';
4	
5	const __dirname = dirname(fileURLToPath(import.meta.url));
6	export const ROOT = resolve(__dirname, '..');
7	
8	/**
9	 * 确保有 config.json：缺失时从 config.example.json 自动复制（同事首次解压常见）。
10	 * @returns {string} 实际使用的配置路径
11	 */
12	export function ensureConfigFile() {
13	  const dest = resolve(ROOT, 'config.json');
14	  if (existsSync(dest)) return dest;
15	  const ex = resolve(ROOT, 'config.example.json');
16	  if (existsSync(ex)) {
17	    copyFileSync(ex, dest);
18	    console.warn(
19	      `[WARN] 未找到 config.json，已从 config.example.json 自动生成。\n` +
20	        `       请编辑 ${dest}\n` +
21	        `       - feishuWebhooks：自己的飞书机器人\n` +
22	        `       - storeList：要盯的店名\n` +
23	        `       - fullRun 保持 false\n`,
24	    );
25	    return dest;
26	  }
27	  // 最后兜底写一份最小配置，避免直接崩
28	  const minimal = {
29	    feishuWebhooks: [],
30	    intervalMinutes: 15,
31	    stores: 'all',
32	    storeList: ['Agnis', 'HomeCove', 'Twilight Cove'],
33	    fullRun: false,
34	    headless: true,
35	    proxy: '',
36	    userDataDir: './.userdata',
37	    channel: 'chrome',
38	  };
39	  writeFileSync(dest, JSON.stringify(minimal, null, 2), 'utf8');
40	  console.warn(`[WARN] 已写入最小 config.json：${dest}（请补飞书 webhook 与 storeList）`);
41	  return dest;
42	}
43	
44	/** 读取并规范化 config.json */
45	export function loadConfig() {
46	  const path = ensureConfigFile();
47	  const raw = JSON.parse(readFileSync(path, 'utf8'));
48	  return {
49	    // 告警目标群 webhook：支持单个字符串或数组（多个群同发）。兼容旧字段 feishuWebhook。
50	    feishuWebhooks: (Array.isArray(raw.feishuWebhooks)
51	      ? raw.feishuWebhooks
52	      : [raw.feishuWebhooks ?? raw.feishuWebhook ?? ''])
53	      .map((s) => String(s || '').trim()).filter(Boolean),
54	    feishuSecret: raw.feishuSecret || '',
55	    intervalMinutes: Number(raw.intervalMinutes) || 15,
56	    stores: raw.stores || 'all',
57	    // 多店会话切店清单（店名与卖家中心顶栏英文名一致）。默认三店。
58	    storeList: Array.isArray(raw.storeList)
59	      ? raw.storeList
60	      : ['Agnis', 'HomeCove', 'Twilight Cove'],
61	    // 默认 false：本机只跑浏览器流量，不碰赛狐（避免同事电脑无白名单报错）。
62	    // 上下架请用服务器 `npm run sellfox:start`，或显式 fullRun:true / FULL_RUN=1 联调。
63	    fullRun: raw.fullRun === true || process.env.FULL_RUN === '1' || process.env.FULL_RUN === 'true',
64	    alerts: {
65	      onSaleDrop: raw.alerts?.onSaleDrop !== false,
66	      trafficAnomaly: raw.alerts?.trafficAnomaly !== false,
67	      // 赛狐下架 / 上架点名（fullRun 时启用，默认都开）
68	      delist: raw.alerts?.delist !== false,
69	      onshelf: raw.alerts?.onshelf !== false,
70	      // 登录过期/连续监测失败时发飞书提醒，避免登录态失效后静默死掉没人知道
71	      loginExpiry: raw.alerts?.loginExpiry !== false,
72	    },
73	    // 连续失败达到该轮次才发登录过期告警（默认 2 轮 ≈ 30 分钟，滤掉偶发抖动）
